mapper.select:
SELECT * FROM torn_stock_alpha_daily_snapshot
WHERE stocks_id = #{stocksId}
  AND business_date = #{businessDate}
  AND stock_universe_version = #{stockUniverseVersion}
  AND alpha_rule_version = #{alphaRuleVersion}
  AND deleted = 0
FOR UPDATE

SELECT business_date
FROM torn_stock_alpha_daily_snapshot
WHERE stock_universe_version = #{stockUniverseVersion}
  AND alpha_rule_version = #{alphaRuleVersion}
  AND common_valid = true
  AND deleted = 0
  AND business_date BETWEEN #{startDate} AND #{endDate}
GROUP BY business_date
HAVING COUNT(DISTINCT stocks_id) = #{memberCount}
ORDER BY business_date
